def build(run):
    """Replay STEPS. run(argv, author, date) -> stdout of nb. Returns {name: id}."""
    ids = {}
    for name, author, date, argv in STEPS:
        out = run([a.format(**ids) for a in argv], author, date)
        if name:
            ids[name] = out.strip().split()[-1]
    return ids
